# UC‑01 Collector (`connection_collect.py` @ `c7acf13`) — Independent Static Review

## 0. Method, and one hard limitation on evidence

Every defect below was **reproduced by executing** the reviewed expressions, not inferred by reading. The reviewed checkout is **not present in this environment** (`/home/user/webapp/my-bro` does not exist here), so I could not import `connection_collect.py` itself. I therefore copied the reviewed functions **verbatim** from the supplied source text into two standalone harnesses and stubbed only the *external* dependencies they call (`mttd.field/to_ms`, `mttd.require`-equivalent `require`, `visibility_observer.REQUEST_SECONDS` / `JITTER_NS` / `POLL_NS`, and the module-level constants `POLL_MS`, `REQUEST_MS`, `JITTER_MS`, `STATES`, `CANARY_RULES`).

Two consequences I will not paper over:

- **I could not execute the project's own suite**, so any statement about "the shipped tests" is a statement about the supplied test source text, not an executed result.
- **Line numbers are not cited**, because I cannot read the real files to count lines and will not invent them. Findings are anchored to the enclosing function with the exact verbatim expression quoted instead.

Self-contained harness (stdlib only; paste and run — prints every observation quoted in §2):

```python
#!/usr/bin/env python3
"""UC-01 review probes. Verbatim copies of reviewed functions; external helpers stubbed."""
import os, re, stat
from datetime import datetime, timezone

BASE = 1790121600000                      # 2026-09-23T00:00:00Z (a Wednesday)

# ---- STUBS for external helpers only -------------------------------------------------
class _M:
    def field(self, raw, key):
        cur = raw
        for p in key.split('.'):
            if not isinstance(cur, dict) or p not in cur: return None
            cur = cur[p]
        return cur
    def to_ms(self, ts):
        return int(datetime.fromisoformat(ts.replace('Z','+00:00')).timestamp()*1000)
m = _M()
def require(cond, code):
    if not cond: raise ValueError(code)
class _V: REQUEST_SECONDS = .75; JITTER_NS = 100_000_000; POLL_NS = 1_000_000_000
v = _V()
def banner(t): print('\n'+'='*72+'\n'+t+'\n'+'='*72)

# ---- VERBATIM constants (connection_measure.py) --------------------------------------
WINDOW_MS = 300000; POLL_MS = 5000; JITTER_MS = 1000; REQUEST_MS = 2000
STATES = {'active','disconnected','pending','never_connected','error'}
CANARY_RULES = {'linux': {'554':5,'100201':7,'100301':7}, 'windows': {'554':5,'100304':7}}

# ---- VERBATIM: keys/text/integer/timestamp/point/check_plan/classify -----------------
def keys(value, expected, code):
    require(isinstance(value, dict) and set(value) == set(expected.split()), code)
def text(value, code):
    require(isinstance(value,str) and 1<=len(value)<=1024 and bool(value.strip()) and
            not any(ord(c)<32 or ord(c)==127 for c in value), code)
def integer(value, low, high, code):
    require(type(value) is int and low <= value <= high, code)
def timestamp(value): integer(value, 0, 253402300799999, 'TIMESTAMP')
def point(p, role, raw):
    c = p['clocks'][role]; value = raw - c['offset_ms']
    error = c['precision_ms'] + c['uncertainty_ms']
    return value - error, value + error
def check_plan(p):
    keys(p, 'schema_version kind run_id protocol_ref identity clocks cycles window_s poll_interval_ms coverage', 'PLAN_KEYS')
    require(type(p['schema_version']) is int and p['schema_version']==1 and p['kind']=='uc01_connection_plan','PLAN_VERSION')
    text(p['run_id'],'RUN_ID'); text(p['protocol_ref'],'PROTOCOL_REF')
    keys(p['identity'],'manager_name agent_id agent_name os config_sha256','IDENTITY_KEYS')
    for value in p['identity'].values(): text(value,'IDENTITY_TEXT')
    require(re.fullmatch(r'[0-9]{3,8}', p['identity']['agent_id']) and int(p['identity']['agent_id'])!=0,'ENDPOINT_AGENT_REQUIRED')
    require(p['identity']['os'] in {'linux','windows'},'OS')
    require(re.fullmatch(r'[0-9a-f]{64}', p['identity']['config_sha256']),'CONFIG_HASH')
    keys(p['clocks'],'controller endpoint manager observer','CLOCK_ROLES')
    for c in p['clocks'].values():
        keys(c,'offset_ms uncertainty_ms precision_ms ref','CLOCK_KEYS')
        integer(c['offset_ms'],-60000,60000,'CLOCK_OFFSET')
        integer(c['uncertainty_ms'],0,60000,'CLOCK_UNCERTAINTY')
        integer(c['precision_ms'],1,60000,'CLOCK_PRECISION')
        text(c['ref'],'CLOCK_REF')
    require(type(p['window_s']) is int and p['window_s']==300 and
            type(p['poll_interval_ms']) is int and p['poll_interval_ms']==POLL_MS,'FIXED_PROTOCOL')
    keys(p['coverage'],'start_ms end_ms ref','COVERAGE_KEYS')
    timestamp(p['coverage']['start_ms']); timestamp(p['coverage']['end_ms'])
    require(p['coverage']['end_ms']>p['coverage']['start_ms'],'COVERAGE_ORDER'); text(p['coverage']['ref'],'COVERAGE_REF')
    require(isinstance(p['cycles'],list) and 5<=len(p['cycles'])<=100,'PLANNED_CYCLES_5_TO_100')
    ids, paths = set(), set()
    for c in p['cycles']:
        keys(c,'cycle_id target_path rule_ids levels','CYCLE_KEYS')
        text(c['cycle_id'],'CYCLE_ID'); text(c['target_path'],'TARGET_PATH')
        path = c['target_path']
        require((path.startswith('/') if p['identity']['os']=='linux' else bool(re.match(r'^[A-Za-z]:\\', path)))
                and not path.endswith(('/','\\')) and
                not any(x in {'.','..',''} for x in re.split(r'[/\\]', path)[1:]),'CANONICAL_TARGET_PATH')
        k = path if p['identity']['os']=='linux' else path.casefold()
        require(c['cycle_id'] not in ids and k not in paths,'DUPLICATE_PLANNED_CYCLE_OR_PATH'); ids.add(c['cycle_id']); paths.add(k)
        require(isinstance(c['rule_ids'],list) and c['rule_ids'] and len(c['rule_ids'])<=16 and
                all(isinstance(x,str) and x.isdecimal() for x in c['rule_ids']) and
                len(set(c['rule_ids']))==len(c['rule_ids']),'RULE_IDS')
        require(isinstance(c['levels'],list) and c['levels'] and len(c['levels'])<=16 and
                all(type(x) is int and 0<=x<=16 for x in c['levels']) and
                len(set(c['levels']))==len(c['levels']),'LEVELS')
        sup = CANARY_RULES[p['identity']['os']]
        require(set(c['rule_ids'])<=set(sup) and set(c['levels'])=={sup[x] for x in c['rule_ids']},'CANARY_CREATION_RULES')
    return p
def classify(p, c, r, alerts):
    out = {'cycle_id': c['cycle_id'], 'state':'MISSING_RECORD','connection_state':'NOT_OBSERVED',
           'transition_interval_s':None,'functional_confirmation_interval_s':None,'alert_refs':[],
           'exclusion_reason':None,'causality_authenticated':False,'acceptance_approved':False}
    def finish(s):
        out['state']=s; return out
    if r is None: return out
    if r['exclusion_reason']:
        out['exclusion_reason']=r['exclusion_reason']; return finish('EXCLUDED')
    if any(abs(x['offset_ms'])>100 or x['uncertainty_ms']>100 for x in p['clocks'].values()):
        return finish('SESSION_CLOCK_LIMIT_EXCEEDED')
    s, polls = r['restart'], r['polls']
    if s is None: return finish('MISSING_RESTART_EVIDENCE')
    t0 = point(p,'controller',s['request_ms'])
    if s['command_end_ms'] is None or s['service_started_ms'] is None: return finish('RESTART_UNPROVEN')
    end = point(p,'controller',s['command_end_ms']); start = point(p,'endpoint',s['service_started_ms'])
    if end[1] < t0[0] or start[1] < t0[0]: return finish('INVALID_TIMELINE')
    if min(start[0],end[0]) < t0[1]: return finish('TIMING_UNCERTAIN')
    if not s['service_running'] or not s['old_instance'] or not s['new_instance'] or s['old_instance']==s['new_instance']:
        return finish('RESTART_UNPROVEN')
    if not polls: return finish('OBSERVATION_INCOMPLETE')
    previous = None; clock = p['clocks']['observer']
    wall_tolerance = 2*(clock['precision_ms']+clock['uncertainty_ms'])
    for q in polls:
        if any(q[k]!=p['identity'][k] for k in ('manager_name','agent_id','agent_name')): return finish('IDENTITY_CHANGED')
        dt = q['end_monotonic_ms']-q['start_monotonic_ms']
        if not 0<=dt<=REQUEST_MS or q['end_ms']<q['start_ms']: return finish('POLL_TIMING_INVALID')
        if abs(q['end_ms']-q['start_ms']-dt)>wall_tolerance: return finish('CLOCK_JUMP')
        if previous:
            gap = q['start_monotonic_ms']-previous['start_monotonic_ms']
            if not POLL_MS-JITTER_MS<=gap<=POLL_MS+JITTER_MS or q['start_monotonic_ms']<previous['end_monotonic_ms']:
                return finish('POLL_GAP')
            if abs(q['start_ms']-previous['start_ms']-gap)>wall_tolerance: return finish('CLOCK_JUMP')
        if abs(q['start_ms']-polls[0]['start_ms']-(q['start_monotonic_ms']-polls[0]['start_monotonic_ms']))>wall_tolerance:
            return finish('CLOCK_JUMP')
        previous = q
    coverage = p['coverage']
    if (point(p,'observer',polls[0]['end_ms'])[1] > t0[0] or
        point(p,'observer',polls[-1]['end_ms'])[0] < t0[1]+WINDOW_MS or
        point(p,'manager',coverage['start_ms'])[1] > t0[0] or
        point(p,'manager',coverage['end_ms'])[0] < t0[1]+WINDOW_MS): return finish('OBSERVATION_INCOMPLETE')
    if any(q['status']=='error' for q in polls): return finish('POLL_ERROR')
    active=None; negative=None
    for q in polls:
        if point(p,'observer',q['start_ms'])[0] < start[1]: continue
        if q['status']=='active':
            active=q
            if negative is not None:
                lower=point(p,'observer',negative['start_ms'])[0]; upper=point(p,'observer',q['end_ms'])[1]
                out['transition_interval_s']=[(lower-t0[1])/1000,(upper-t0[0])/1000]
                out['connection_state']='TRANSITION_OBSERVED'
            else: out['connection_state']='ACTIVE_WITHOUT_TRANSITION_BRACKET'
            break
        negative=q
    if active is None: return finish('NO_ACTIVE_OBSERVED')
    canary=r['canary']
    if canary is None: return finish('CANARY_NOT_SUPPLIED')
    if canary['path']!=c['target_path']: return finish('CANARY_TARGET_MISMATCH')
    created=point(p,'endpoint',canary['created_ms'])
    if created[1]<max(start[0],end[0]): return finish('INVALID_TIMELINE')
    if created[0]<max(start[1],end[1]): return finish('TIMING_UNCERTAIN')
    matches=[a for a in alerts if
             all(a['raw'][o][k]==p['identity'][l] for o,k,l in
                 [('manager','name','manager_name'),('agent','id','agent_id'),('agent','name','agent_name')]) and
             a['raw']['rule']['id'] in c['rule_ids'] and
             a['raw']['rule']['level']==CANARY_RULES[p['identity']['os']][a['raw']['rule']['id']] and
             m.field(a['raw'],'syscheck.path')==c['target_path'] and
             coverage['start_ms']<=m.to_ms(a['raw']['timestamp'])<=coverage['end_ms']]
    if not matches: return finish('CANARY_ALERT_NOT_OBSERVED')
    first=matches[0]; out['alert_refs']=list(first['refs'])
    alert_at=point(p,'manager',m.to_ms(first['raw']['timestamp']))
    if alert_at[1]<created[0]: return finish('PREEXISTING_CANARY_ALERT')
    if alert_at[0]<created[1]: return finish('TIMING_UNCERTAIN')
    corr=next((q for q in polls if q['status']=='active' and point(p,'observer',q['start_ms'])[0]>=alert_at[1]),None)
    if corr is None: return finish('ACTIVE_NOT_CORROBORATED_AFTER_CANARY')
    active_at=point(p,'observer',corr['end_ms'])
    lower=max(alert_at[0],active_at[0],end[0],start[0])-t0[1]
    upper=max(alert_at[1],active_at[1],end[1],start[1])-t0[0]
    out['functional_confirmation_interval_s']=[lower/1000,upper/1000]
    if upper<=WINDOW_MS: return finish('FUNCTIONAL_EVIDENCE_WITHIN_WINDOW')
    if lower>WINDOW_MS: return finish('FUNCTIONAL_EVIDENCE_LATE')
    return finish('TIMING_UNCERTAIN')

# ---- VERBATIM: classify_source (source_observer.py) + its MAX_FILE/STAT_KEYS ----------
MAX_FILE = 65536
STAT_KEYS = ('st_dev','st_ino','st_mode','st_nlink','st_uid','st_gid','st_size','st_mtime_ns','st_ctime_ns')
def check_identity(info, size):
    require(isinstance(info,dict) and set(info)==set(STAT_KEYS) and all(type(n) is int for n in info.values()),'SOURCE_CHANGED')
    require(stat.S_ISREG(info['st_mode']) and info['st_nlink']==1 and info['st_uid']==os.geteuid() and
            not info['st_mode']&0o077,'PRIVATE_SOURCE_REQUIRED')
    require(0<=info['st_size']<=MAX_FILE and info['st_size']==size,'SOURCE_TOO_LARGE')
def classify_source(s, polls):
    previous=None
    for i,p in enumerate(polls):
        require(set(p)=={'start_ms','end_ms','start_ns','end_ns','found','sha256','identity'},'POLL_KEYS')
        require(all(type(p[k]) is int and p[k]>=0 for k in ('start_ms','end_ms','start_ns','end_ns')),'POLL_TIME')
        require(type(p['found']) is bool,'POLL_FOUND')
        elapsed=p['end_ns']-p['start_ns']
        require(0<=elapsed<=int(v.REQUEST_SECONDS*1e9),'READ_OVERRUN')
        require(p['end_ms']>=p['start_ms'] and abs((p['end_ms']-p['start_ms'])*1e6-elapsed)<=v.JITTER_NS,'CLOCK_JUMP')
        if previous is not None:
            gap=p['start_ns']-previous['start_ns']
            require(abs(gap-v.POLL_NS)<=v.JITTER_NS and p['start_ns']>=previous['end_ns'],'POLL_GAP')
            require(abs((p['start_ms']-previous['start_ms'])*1e6-gap)<=v.JITTER_NS,'CLOCK_JUMP')
        if p['found']:
            require(i==len(polls)-1 and p['sha256']==s['expected_sha256'],'WRONG_CONTENT')
            check_identity(p['identity'],p['identity']['st_size'])
            if previous is None: return 'preexisting', None
            return 'observed', {'run_id':s['run_id'],'trial_id':s['trial_id'],'device':s['device'],
                'clock_ref':s['clock_ref'],'kind':'action_confirmed','timestamp_ms':p['end_ms'],
                'precision_ms':p['end_ms']-previous['start_ms']+s['precision_ms'],
                'last_negative_start_ms':previous['start_ms'],'first_positive_end_ms':p['end_ms'],
                'target_key':{'syscheck.path':s['directory']+'/'+s['filename']}}
        require(p['sha256'] is None and p['identity'] is None,'ABSENCE_METADATA')
        previous=p
    return 'not_observed', None

# ---- VERBATIM: check_times (connection_collect.py) -----------------------------------
def check_times(entries, kind, plan):
    role = 'observer' if kind == 'manager' else 'endpoint'
    clock = plan['clocks'][role]; tolerance = 2*(clock['precision_ms']+clock['uncertainty_ms'])
    for i,q in enumerate(entries):
        for key in ('start_ms','end_ms','start_monotonic_ms','end_monotonic_ms'): timestamp(q[key])
        elapsed=q['end_monotonic_ms']-q['start_monotonic_ms']
        require(0<=elapsed<=REQUEST_MS and q['end_ms']>=q['start_ms'],'QUERY_OVERRUN')
        require(abs(q['end_ms']-q['start_ms']-elapsed)<=tolerance,'CLOCK_JUMP')
        if i:
            prev=entries[i-1]; gap=q['start_monotonic_ms']-prev['start_monotonic_ms']
            require(POLL_MS-JITTER_MS<=gap<=POLL_MS+JITTER_MS and q['start_monotonic_ms']>=prev['end_monotonic_ms'],'POLL_GAP')
            require(abs(q['start_ms']-entries[0]['start_ms']-(q['start_monotonic_ms']-entries[0]['start_monotonic_ms']))<=tolerance,'CLOCK_JUMP')

# ---- FIXTURES ------------------------------------------------------------------------
def build_plan(os_name='linux', observer=(1,0,1)):
    rules = ['554','100201'] if os_name=='linux' else ['554','100304']
    cycles=[{'cycle_id':f'cycle-{i}',
             'target_path': (f'/tmp/uc01/canary{i}.dat' if os_name=='linux' else f'C:\\uc01\\canary{i}.dat'),
             'rule_ids':rules,'levels':[CANARY_RULES[os_name][r] for r in rules]} for i in range(5)]
    return {'schema_version':1,'kind':'uc01_connection_plan','run_id':'run-1','protocol_ref':'proto-1',
            'identity':{'manager_name':'manager','agent_id':'001','agent_name':'endpoint','os':os_name,'config_sha256':'a'*64},
            'clocks':{'controller':{'offset_ms':0,'uncertainty_ms':0,'precision_ms':1,'ref':'ctrl'},
                      'endpoint':{'offset_ms':0,'uncertainty_ms':0,'precision_ms':1100,'ref':'endpoint'},
                      'manager':{'offset_ms':0,'uncertainty_ms':50,'precision_ms':50,'ref':'manager'},
                      'observer':{'offset_ms':0,'uncertainty_ms':observer[1],'precision_ms':observer[0],'ref':'observer'}},
            'cycles':cycles,'window_s':300,'poll_interval_ms':POLL_MS,
            'coverage':{'start_ms':BASE-10000,'end_ms':BASE+400000,'ref':'cov-1'}}
def build_record(plan, drift=8, drift_from=5):
    polls=[]
    for i in range(64):
        d = drift if i>=drift_from else 0; sm = BASE-5000+5000*i+d
        polls.append({'start_ms':sm,'end_ms':sm+10,'start_monotonic_ms':i*5000,'end_monotonic_ms':i*5000+10,
                      'status':'active' if i>=10 else 'disconnected','manager_name':'manager','agent_id':'001',
                      'agent_name':'endpoint','ref':f's{i}'})
    return {'schema_version':1,'run_id':plan['run_id'],'cycle_id':'cycle-0','exclusion_reason':None,'reason':None,
            'restart':{'request_ms':BASE,'command_end_ms':BASE+5000,'old_instance':'boot:aaa','new_instance':'boot:bbb',
                       'service_started_ms':BASE+3000,'service_running':True,'ref':'restart-ref'},
            'canary':{'created_ms':BASE+20000,'path':plan['cycles'][0]['target_path'],'source_ref':'src'},'polls':polls}
def build_alerts(plan):
    return [{'raw':{'manager':{'name':'manager'},'agent':{'id':'001','name':'endpoint'},
                    'rule':{'id':'554','level':5},'syscheck':{'path':plan['cycles'][0]['target_path']},
                    'timestamp':'2026-09-23T00:00:25.000Z'},'refs':['alerts:1']}]
def run_classify(plan, drift=8):
    return classify(plan, plan['cycles'][0], build_record(plan,drift), build_alerts(plan))

# ---- PROBES --------------------------------------------------------------------------
banner('UC01-02  untyped == in intent/terminal')
lit = {'intent_sha256':'a'*64,'status':'complete','count':1,'reason':None}
for c in (True, 1.0, 1):
    print(f'  terminal count={c!r:5} == literal ->', {'intent_sha256':'a'*64,'status':'complete','count':c,'reason':None} == lit)
print('  range(True)==range(1):', list(range(True))==list(range(1)))
try: range(64.0)
except TypeError as e: print('  range(64.0) ->', type(e).__name__, e)
ib = {'schema_version':1,'kind':'service','cycle_id':'cycle-0','capture_id':'0'*32,
      'plan_sha256':'b'*64,'source_sha256':{},'acceptance_approved':False}
for v_ in (True, 0, 0.0):
    print(f'  intent schema_version={v_!r}, acceptance_approved=0 == expected ->', dict(ib, schema_version=v_, acceptance_approved=0) == ib)

banner('UC01-01  source export None')
spec = {'schema_version':1,'run_id':'run-1','trial_id':'cycle-0','device':'endpoint','clock_ref':'endpoint',
        'directory':'/tmp/uc01','filename':'canary.dat','expected_sha256':'c'*64,'seconds':2,'precision_ms':1}
ident = {'st_dev':1,'st_ino':2,'st_mode':stat.S_IFREG|0o600,'st_nlink':1,'st_uid':os.geteuid(),
         'st_gid':os.getegid(),'st_size':21,'st_mtime_ns':1,'st_ctime_ns':1}
first_positive = [{'start_ms':1,'end_ms':2,'start_ns':0,'end_ns':10**6,'found':True,
                   'sha256':spec['expected_sha256'],'identity':ident}]
print('  classify_source(first-poll positive) ->', classify_source(spec, first_positive))
print('  export() returns -> None')
try: None['run_id']
except TypeError as e: print('  bind() event["run_id"] ->', type(e).__name__, ':', e)

banner('UC01-03  manager-kind timing judged by clocks["observer"]')
ent = [{k:q[k] for k in ('start_ms','end_ms','start_monotonic_ms','end_monotonic_ms')}
       for q in build_record(build_plan(), drift=8)['polls']]
for label, obs in (('observer tol 2 ms  ', (1,0,1)), ('observer tol 200 ms', (50,50,50))):
    try:
        check_times(ent,'manager',build_plan(observer=obs)); r='ACCEPTED'
    except ValueError as e: r=f'rejected: {e}'
    print(f'  identical 64-poll data, {label} -> {r}')
pm = build_plan(observer=(1,0,1)); pm['clocks']['manager']={'offset_ms':0,'uncertainty_ms':50000,'precision_ms':60000,'ref':'manager'}
try:
    check_times(ent,'manager',pm); r='ACCEPTED'
except ValueError as e: r=f'rejected: {e}'
print(f'  identical data, manager tol 120000 ms -> {r}   (never consulted)')

banner('UC01-04  check_plan envelope vs classify acceptance')
for label, mut in (('uncertainty 200', lambda p: p['clocks']['observer'].update(uncertainty_ms=200)),
                   ('offset 101',      lambda p: p['clocks']['observer'].update(offset_ms=101)),
                   ('precision 60000', lambda p: p['clocks']['observer'].update(precision_ms=60000))):
    p = build_plan(); mut(p)
    try: check_plan(p); ok='accepted'
    except ValueError as e: ok=f'rejected: {e}'
    print(f'  {label:16} check_plan -> {ok:9} classify -> {run_classify(p, drift=0)["state"]}')

banner('UC01-06  left-censored activation counts as success')
p = build_plan(observer=(50,50,50)); rec = build_record(p, drift=0)
for q in rec['polls']: q['status']='active'
o = classify(p, p['cycles'][0], rec, build_alerts(p))
print('  all polls active ->', {k:o[k] for k in ('state','connection_state','functional_confirmation_interval_s')})
p2 = build_plan(observer=(50,50,50)); o2 = classify(p2, p2['cycles'][0], build_record(p2, drift=0), build_alerts(p2))
print('  bracketed control ->', {k:o2[k] for k in ('state','connection_state','transition_interval_s')})

banner('UC01-08  systemd timestamp string')
rx = r'[A-Z][a-z]{2} \d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2} UTC'
for value in ('Wed 2026-09-23 00:50:00 UTC','Mon 2026-09-23 00:50:00 UTC','Wed 2026-09-23 03:50:00 +03'):
    mm = bool(re.fullmatch(rx, value))
    try: d=datetime.strptime(value,'%a %Y-%m-%d %H:%M:%S UTC'); s=f'parsed {int(d.replace(tzinfo=timezone.utc).timestamp())*1000}'
    except ValueError as e: s=f'ValueError: {e}'
    print(f'  {value!r:32} regex={str(mm):5} {s}')
print('  2026-09-23 is a', datetime(2026,9,23).strftime('%A'))

banner('UC01-05  declared vs real per-sample bound')
print('  check_times bound: 0 <= elapsed <= REQUEST_MS(2000);  2000 ->', 0<=2000<=REQUEST_MS, ', 2001 ->', 0<=2001<=REQUEST_MS)
print('  native_sample -> r.bounded_process(argv, 1.5); cleanup adds proc.wait(timeout=2) => worst case ~3500 ms')

banner('UC01-07  windows plan')
w = build_plan(os_name='windows')
try: check_plan(w); print('  check_plan(os="windows") -> accepted')
except ValueError as e: print('  check_plan ->', e)
try: require('service'=='service' and w['identity']['os']=='linux','LINUX_SYSTEMD_ONLY')
except ValueError as e: print('  normalize()/capture() service guard ->', e)

banner('NON-DEFECTS (verified)')
try: check_times(ent,'manager',build_plan(observer=(50,50,50))); print('  intact 64-poll 315 s schedule -> ACCEPTED')
